#  ★제목: 시리즈 틀 금지(229 districts·Age-standardized), 쌍점 금지, 질문형. 단독 저자 무인칭. Results 숫자만, Discussion 숫자 없음. 미국식 철자.
#  ★공공체육시설은 최적 WAIC KH(III)·IV에서 1 포함 → '강건' 금지. Spatial+·RSR 표는 결과와 무관하게 보충에 전부. 잔차 Moran 양측(관측 I·기대값·p). P90/P10 작음 → 격차 과장 금지.
import os, json
from content_hbp_intro_methods import INTRO as _INTRO, METHODS as _M0
HERE = os.path.dirname(os.path.abspath(__file__)); N = json.load(open(os.path.join(HERE, "numbers_hbp.json")))
def th(x, d=0): return f"{x:,.{d}f}"
def f3(r): return f"{r[0]:.3f} ({r[1]:.3f}-{r[2]:.3f})"
def ci(k, src="main"):
    e, lo, hi = (N[src][k] if isinstance(src, str) else src); return f"{e:.3f} (95% CrI {lo:.3f}-{hi:.3f})"
def tc(k, src): return f3(N[src][k] if isinstance(src, str) else src)
def cs(k, src="main"):
    e, lo, hi = N[src][k]; return f"RR {e:.3f}; 95% CrI {lo:.3f}-{hi:.3f}"
def nco(t, k): return f3(N["nco"][f"{t}|{k}"])
def pct(x): return f"{100 * x:.0f}%"
R = N["rate"]; RA = N.get("rate_aux", {}); G = N["gate"]; MV = N["mv"]; HC = N["hc"]
KHS = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
def rng(k, srcs=KHS): v = [N[s][k][0] for s in srcs]; return f"{min(v):.3f}-{max(v):.3f}"
kh_best = min(("KH_typeII", "KH_typeIII", "KH_typeIV"), key=lambda t: N[t + "_waic"]); KHB = {"KH_typeII": "II", "KH_typeIII": "III", "KH_typeIV": "IV"}[kh_best]

TITLE = "Does elevated blood pressure at Korean health screening track treated or newly suspected hypertension across districts?"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower()
KEYWORDS = "Hypertension; Metabolic syndrome; Mass screening; Antihypertensive agents; Small-area analysis; Republic of Korea"
RUNNING = "Elevated blood pressure at screening in Korean districts"
GH, GC = N["gi_hot_sido"], N["gi_cold_sido"]
def top(d, n=2): return sorted(d.items(), key=lambda x: -x[1])[:n]

ABSTRACT = [
("Background", "The elevated blood pressure criterion of the metabolic syndrome counts both measured elevation and antihypertensive treatment, so area differences in it may reflect treated or untreated hypertension."),
("Methods", f"This ecological study used national screening statistics for {N['n_districts']} Korean districts, 2019-2024 ({N['cases_total_m']:.1f} million of {N['exam_total_m']:.1f} million examinees met the criterion). Expected counts were approximately standardized for sex and age. Bayesian spatio-temporal models related counts to 10 district characteristics, with space-time interactions, alternative denominators and periods, and comparison outcomes of treated and newly suspected hypertension."),
("Results", f"Nationally, the share meeting the criterion rose from {G['pct']['2013']:.1f}% (2013) to {G['pct']['2024']:.1f}% (2024), whereas measured systolic pressure of 130 mm Hg or higher stayed at {G['sbp_min']:.0f}-{G['sbp_max']:.0f}%. District standardized ratios ranged from {N['sir_p10']:.2f} to {N['sir_p90']:.2f} (10th-90th percentile) with a stable ranking. In the principal model, per standard deviation, the criterion was higher with more public assistance recipients (rate ratio 1.013) and obesity (1.003) and lower with more public sports facilities (0.992). The sports facility association was uncertain in the best-fitting space-time model, none of the 3 persisted with population-based denominators, and the 10 characteristics explained {N['vp']['fixed_hypothesis']:.0f}% of the variance of the linear predictor. Point estimates for public assistance pointed toward treated and those for sports facilities toward newly suspected hypertension."),
("Conclusions", "The geography of elevated blood pressure at screening was stable, but the district characteristics examined explained little of it and their associations depended on model specification. Because the criterion counts treatment, treated and untreated blood pressure should be distinguished when areas are compared."),
]

INTRO = _INTRO
GT = {"n_districts": N["n_districts"], "n_rows": th(N["n_rows"]), "gate_r_min": G["r_min"], "gate_r_max": G["r_max"], "gate_ratio_2013": G["ratio2013"], "gate_ratio_2024": G["ratio2024"],
      "gate_sbp_min": G["sbp_min"], "gate_sbp_max": G["sbp_max"], "exam2018_m": G["exam2018_m"], "f2018": G["f2018"]}
METHODS = [tuple([h] + [p.format(**GT) for p in ps]) for h, *ps in _M0]
METHODS += [
("Statistical analysis",
 "Counts were modeled with a negative binomial likelihood, chosen over the Poisson by the widely applicable information criterion (WAIC) in models with the fixed adjustments only [@gelman2014understanding], with the log of expected counts as the offset, a Besag-York-Mollié 2 district effect on a contact graph of 593 neighboring pairs [@besag1991bayesian; @riebler2016intuitive], and first-order random-walk and independent year effects. Because the criterion is common, rate ratios (RRs) from these count models are interpreted as ratios of standardized prevalence rather than odds ratios, as recommended for common binary outcomes in individual-level analyses [@zou2004modified; @barros2003alternatives]. Penalized complexity priors were used (probability 0.01 that a standard deviation exceeds 0.5; probability 2/3 that the spatial mixing parameter is below 0.5) [@simpson2017penalising]. Characteristics were standardized to 1 SD and reported as RRs with 95% credible intervals (CrIs); an association was credible when the CrI excluded 1. Models were fitted with integrated nested Laplace approximation [@rue2009approximate] (R-INLA 25.10.19, 1 thread, fixed random seeds) in R 4.6.0 [@web:rcore2026]; the principal model was fitted twice to check reproducibility. Residual spatial autocorrelation was tested with a two-sided permutation test of Moran's I against its expectation under no autocorrelation. Hot and cold spots of the 6-year ratio were identified with the Getis-Ord Gi* statistic on the same graph including each district itself (P < .05, without correction for multiple testing) [@ord1995local], and stability with yearly Moran's I and Kendall's W.",
 "Robustness was assessed in 5 prespecified ways. First, 200 models used random subsets of the 10 characteristics, always with the 5 adjustments [@steegen2016increasing]; a characteristic was subset-stable when its CrI excluded 1 in at least 75% of subsets containing it with at least 95% sign agreement. Second, Knorr-Held space-time interaction types I-IV were added [@knorrheld2000bayesian]; within these, an association was considered stable to space-time structure only if it remained credible in the space-time model with the lowest WAIC. The negative binomial principal model was fixed by the prespecified likelihood rule, and models with space-time interactions or other likelihoods could fit better. Third, Spatial+ [@dupont2022spatial], restricted spatial regression [@hodges2010adding], province-by-year random effects, a second-order random-walk year effect, characteristics lagged by 1 and 2 years, alternative district effects, and Poisson, Poisson-lognormal,, binomial, beta-binomial, and binomial with an observation-level random effect likelihoods were fitted [@harrison2015comparison]. Fourth, the principal model was refitted with 2 comparison outcomes from the same screening statistics, standardized in the same way: examinees already treated for hypertension, and examinees newly suspected of hypertension (systolic pressure of 140 mm Hg or higher or diastolic pressure of 90 mm Hg or higher without treatment); both come from other screening tables with all first-stage examinees as the denominator, do not partition the criterion, and were used only as comparisons; differences between their coefficients were not formally tested. Fifth, the model was refitted with a 577-pair queen contiguity graph, without the age-80 adjustment, with unstandardized expected counts, with population-based expected counts, for 2013-2017, and for 2013-2024 including 2018. E-values were computed for credible associations [@vanderweele2017sensitivity], and the share of the variance of the linear predictor attributable to the characteristics was estimated from posterior means. Reporting followed the STROBE statement [@vonelm2007strengthening].",
 "The Institutional Review Board of Hongik University approved the study on November 4, 2025 (7002340-202511-HR-012) and its continuing review on November 3, 2026 (7002340-202611-HR-040), and waived informed consent because only published aggregate statistics were used."),
]

def gi_list(d):
    it = sorted(d.items(), key=lambda x: -x[1]); parts = [f"{v} in {k}" for k, v in it]
    return parts[0] if len(parts) == 1 else ", ".join(parts[:-1]) + ", and " + parts[-1]
RESULTS = [
("Elevated blood pressure across districts",
 f"In 2019-2024, {N['cases_total_m']:.1f} million examinees met the criterion among {N['exam_total_m']:.1f} million examined, {R['2019']:.1f}% in 2019 and {R['2024']:.1f}% in 2024 (Table 1; Fig. 1B; Online Resource 1, Table S7). The 6-year standardized ratio ranged from {N['sir_p10']:.2f} to {N['sir_p90']:.2f} between the 10th and 90th percentiles (ratio {N['p90p10']:.2f}; full range {N['sir_min']:.2f}-{N['sir_max']:.2f}). Yearly Moran's I was {N['moran_min']:.2f} to {N['moran_max']:.2f}, Kendall's W was {N['kendall_w']:.2f}, and the rank correlation between 2019 and 2024 was {N['rho_2019_2024']:.2f}.",
 f"Of {N['gi_hot']} hot spots, {gi_list(GH)}; of {N['gi_cold']} cold spots, {gi_list(GC)} (Fig. 1A). The median population density was {HC['hot']['dens']:.0f} per km² in hot spots and {th(HC['cold']['dens'])} in cold spots, and public sports facilities per 100,000 residents were higher in hot spots (Fig. 1C). Over 2019-2024, the district ratio was correlated with the standardized ratios of treated hypertension (Spearman ρ = {N['rho_htnt'][0]:.2f}) and newly suspected hypertension (ρ = {N['rho_undxh'][0]:.2f})."),
("District characteristics",
 f"With the fixed adjustments only, the WAIC was {th(N['waic_forced_pois'],1)} for the Poisson and {th(N['waic_forced'],1)} for the negative binomial likelihood; adding the 10 characteristics changed it to {th(N['waic_main'],1)}, and refitting the same model changed it by {N['refit']['dwaic']:.1f} (Table 2). The criterion was higher with more public assistance recipients ({cs('basic_livelihood_rate')}) and higher obesity ({cs('obesity_rate')}), and lower with more public sports facilities ({cs('public_sport_fac')}). The RR was {tc('walking_rate', 'main')} for walking and {tc('moderate_pa_rate', 'main')} for moderate physical activity; the CrIs of village sports facilities, high-risk drinking, smoking, screening uptake, and internal medicine specialists included 1. The structured district effect accounted for {N['vp']['spatial_structured']:.0f}% of the variance of the linear predictor, the fixed adjustments for {N['vp']['fixed_forced_controls']:.0f}%, and the 10 characteristics for {N['vp']['fixed_hypothesis']:.0f}%. Residual Moran's I was {N['resid_moran2'][0]:.3f} (expected {N['resid_moran2'][1]:.3f}; two-sided P = {N['resid_moran2'][2]:.2f}), giving no evidence of positive residual autocorrelation."),
("Robustness",
 f"Public assistance, obesity, and sports facilities were credible in all {MV['basic_livelihood_rate'][2]}, {MV['obesity_rate'][2]}, and {MV['public_sport_fac'][2]} covariate subsets that contained them; walking was credible in {pct(MV['walking_rate'][0])}. These subsets vary covariates only. Across Knorr-Held types I-IV, the RR ranged from {rng('basic_livelihood_rate')} for public assistance and {rng('obesity_rate')} for obesity, all credible; for sports facilities it ranged from {rng('public_sport_fac')}, and the CrI included 1 in type {KHB}, which had the lowest WAIC ({th(N[kh_best + '_waic'],1)}), and in type IV (Fig. 2; Online Resource 1, Table S3). Walking was credible in types III and IV only. With Spatial+, the RRs were {tc('basic_livelihood_rate', 'D1_spatial_plus')} for public assistance, {tc('obesity_rate', 'D1_spatial_plus')} for obesity, and {tc('public_sport_fac', 'D1_spatial_plus')} for sports facilities. With restricted spatial regression, they were {tc('basic_livelihood_rate', 'RSR')}, {tc('obesity_rate', 'RSR')}, and {tc('public_sport_fac', 'RSR')}, and walking was {tc('walking_rate', 'RSR')}; without a district effect, the public assistance RR was {tc('basic_livelihood_rate', 'no_spatial')}. With characteristics lagged by 2 years, the RRs were {tc('basic_livelihood_rate', 'E2_lag2')}, {tc('obesity_rate', 'E2_lag2')}, and {tc('public_sport_fac', 'E2_lag2')}. Without the age-80 adjustment, the sports facility RR was {tc('public_sport_fac', 's2')}.",
 f"A binomial likelihood with an observation-level random effect had the lowest WAIC ({th(N['lik5']['binomial_olre'],1)}, compared with {th(N['lik5']['nbinomial'],1)} for the negative binomial); its odds ratios were {f3(N['lik5c']['binomial_olre|basic_livelihood_rate'])} for public assistance, {f3(N['lik5c']['binomial_olre|obesity_rate'])} for obesity, and {f3(N['lik5c']['binomial_olre|ext__public_sport_fac_per100k'])} for sports facilities. With population-based expected counts, the RRs were {tc('basic_livelihood_rate', 'sp')}, {tc('obesity_rate', 'sp')}, and {tc('public_sport_fac', 'sp')}; in 2013-2017, {tc('basic_livelihood_rate', 'aux')}, {tc('obesity_rate', 'aux')}, and {tc('public_sport_fac', 'aux')}; and in 2013-2024 including 2018, {tc('basic_livelihood_rate', 'full')}, {tc('obesity_rate', 'full')}, and {tc('public_sport_fac', 'full')} (Online Resource 1, Table S4). E-values were {N['evalue']['basic_livelihood_rate'][0]:.2f} (CrI limit {N['evalue']['basic_livelihood_rate'][1]:.2f}) for public assistance, {N['evalue']['obesity_rate'][0]:.2f} ({N['evalue']['obesity_rate'][1]:.2f}) for obesity, and {N['evalue']['public_sport_fac'][0]:.2f} ({N['evalue']['public_sport_fac'][1]:.2f}) for sports facilities. The negative-control exposures had RRs of {f3(N['nc']['hit_and_run_rate'])}, {f3(N['nc']['traffic_culture_index'])}, and {f3(N['nc']['fires_per_10000'])}."),
("Comparison outcomes",
 f"For examinees already treated for hypertension, the RR was {nco('HTNTC', 'basic_livelihood_rate')} for public assistance, {nco('HTNTC', 'obesity_rate')} for obesity, and {nco('HTNTC', 'public_sport_fac')} for sports facilities. For examinees newly suspected of hypertension, the corresponding RRs were {nco('UNDXHC', 'basic_livelihood_rate')}, {nco('UNDXHC', 'obesity_rate')}, and {nco('UNDXHC', 'public_sport_fac')}, and the RR was {nco('UNDXHC', 'im_specialists')} for internal medicine specialists (Fig. 2; Online Resource 1, Table S5)."),
]

DISCUSSION = [
"Elevated blood pressure at screening, as defined for the metabolic syndrome, varied modestly across Korean districts with a stable ranking, and its national rise was consistent with a growing treated component. In the principal model, it was higher where more residents received public assistance and where self-reported obesity was higher, and lower where public sports facilities were more numerous. None of these associations was robust across specifications: the sports facility association was uncertain in the best-fitting space-time model, and none persisted with population-based denominators. The 10 characteristics accounted for a small share of the modeled variation, most of which was spatially structured, so the characteristics examined explained little of a stable geography.",
"### What the criterion counts",
"The metabolic syndrome criterion counts examinees with measured elevation and those taking antihypertensive drugs together [@grundy2005diagnosis; @alberti2009harmonizing]. Nationally, the share meeting it rose while the share with measured systolic elevation did not, which is consistent with more examinees being treated, as treatment of hypertension has expanded in Korea [@kim2021ten; @kim2026korea]. This inference is indirect, because diastolic pressure of 85-89 mm Hg could not be separated, treated examinees may also have measured elevation, and the comparison was not age-standardized. Even so, a district with more treated hypertension can show more elevated blood pressure at screening when blood pressure is well controlled, so area comparisons that use this criterion combine burden and care in one count.",
"### Public assistance and treated hypertension",
"The point estimate for public assistance was further from 1 for treated hypertension than for newly suspected hypertension, whose CrI was wide, and the 2 coefficients were not compared formally. Lower socioeconomic status is associated with hypertension [@leng2015socioeconomic], and in Korea, under universal health insurance, lower socioeconomic position has been associated with a higher prevalence of hypertension [@lee2017socioeconomic]. The public assistance rate also marks Medical Aid coverage, which changes access to care, so a gradient that is clearer for treated hypertension may reflect established treated hypertension, care access, or both. The association disappeared when the district effect was removed or made orthogonal to the characteristics and did not persist with population-based expected counts, in 2013-2017, or over 2013-2024, so it cannot be separated from the spatial structure of districts or from the selection of examinees, and it cannot be attributed to recipients themselves.",
"### Sports facilities and physical activity",
"Exercise lowers blood pressure [@cornelissen2013exercise], and walkable neighborhoods have been associated with a lower incidence of hypertension [@sarkar2018neighbourhood; @chiu2016moving], but sports facilities per resident are a coarse district indicator rather than a measure of the built environment around individuals. The sports facility estimate was below 1 for newly suspected but not for treated hypertension. However, it was small, uncertain in the best-fitting space-time model, with population-based expected counts, with 2-year lags, and without the age-80 adjustment, although it remained credible in 2013-2017 and over 2013-2024. Facilities per resident are highest in sparsely populated, older districts, where small denominators inflate the rate, and the age structure of examinees was only approximated, so rurality, residual age structure, and regional change may explain the association. Walking and moderate physical activity showed no consistent association. The physical activity hypotheses were therefore not supported, and no claim about facilities as a lever on blood pressure follows from this analysis.",
"### Implications for comparing areas",
"Regional differences in hypertension management have been reported in Korea [@lee2019temporal], and regional factors have been related to hypertension prevalence [@lee2025regional]. The present results suggest a practical caution for clinicians and planners who use screening-based metabolic syndrome components to compare populations: the blood pressure component mixes untreated elevation with treatment, its area differences were modest and stable, and they were not well explained by the district characteristics examined. Reporting treated and untreated blood pressure separately, with age-standardized denominators of examinees, would make such comparisons more informative.",
"### Strengths and limitations",
"The analysis covered every district for 6 years under one criterion, checked the published criterion against the measured blood pressure distribution, fixed the covariate sets before modeling, and tested associations against space-time interactions, alternative likelihoods, denominators and periods, and comparison outcomes. It has limitations. First, it is ecological, and associations do not describe individuals [@morgenstern1995ecologic]. Second, the criterion rests on blood pressure measured once at screening and on self-reported treatment, and measurement practice may differ between screening sites. Third, the published statistics do not separate measured elevation from treatment, and the comparison outcomes come from other tables with different thresholds and denominators, so they do not partition the criterion. Fourth, the examinee age structure of each district was approximated, obesity in 2019 and some public assistance values were imputed, and the main period includes the COVID-19 pandemic, when attendance changed. Fifth, 10 characteristics, 2 comparison outcomes, and many specifications were examined, Gi* clusters were not corrected for multiple testing, the outcome was selected for its spatial structure, and E-values were small, so the associations are fragile to residual confounding. Sixth, the district panel was compiled from public statistics; the outcome, the denominator, and 11 of the 15 modeled characteristics matched a reference district database cell by cell; village sports facilities differed in 14 of 1,374 district-years, and internal medicine specialists, public assistance, and the share aged 80 years or older were not compared cell by cell (Online Resource 1, Table S2).",
]
CONCLUSION = ["Elevated blood pressure at Korean health screening varies modestly and stably across districts, and its national rise is consistent with a growing treated component. District public assistance, obesity, and sports facilities were associated with it only under some specifications and explained little of its geography. Because the criterion counts treatment as well as measured elevation, area comparisons based on it, and on the metabolic syndrome, should distinguish treated from untreated blood pressure."]
